import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { 
  Filter, Search, BookOpen, FileText, 
  ChevronDown, GraduationCap, Layers,
  Calendar, ArrowLeft, ExternalLink, Globe, Sparkles, SlidersHorizontal
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { epreuveAPI, academicAPI, BACKEND_BASE_URL } from '../services/api';
import BackNavBar from './BackNavBar';
import { useBackHandler } from '../hooks/useBackHandler';
import { getDashboardPathForRole } from '../utils/backHandler';
import { getStoredSession } from '../utils/authSession';
import '../Dashboard.css';

const Library = () => {
  const navigate = useNavigate();
  const [epreuves, setEpreuves] = useState([]);
  const [universities, setUniversities] = useState([]);
  const [faculties, setFaculties] = useState([]);
  const [filieres, setFilieres] = useState([]);
  const [matieres, setMatieres] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [filters, setFilters] = useState({
    universityId: '',
    faculteId: '',
    filiereId: '',
    niveau: '',
    session: '',
    matiereId: '',
    type: 'Tous'
  });

  useEffect(() => {
    fetchData();
  }, []);

  useBackHandler(() => {
    const { role } = getStoredSession();
    navigate(getDashboardPathForRole(role), { replace: true });
    return true;
  }, [navigate]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [epreuvesRes, univRes, facRes, filRes, matRes] = await Promise.all([
        epreuveAPI.getAll(),
        academicAPI.getUniversites(),
        academicAPI.getFacultes(),
        academicAPI.getAllFilieres(),
        academicAPI.getAllMatieres()
      ]);
      setEpreuves(epreuvesRes.data);
      setUniversities(univRes.data);
      setFaculties(facRes.data || []);
      setFilieres(filRes.data || []);
      setMatieres(matRes.data || []);
    } catch (err) {
      console.error("Erreur chargement", err);
    } finally {
      setLoading(false);
    }
  };

  // Filtrages dynamiques dépendants pour les sélecteurs
  const filteredFaculties = faculties.filter(f => !filters.universityId || f.universite?.id === parseInt(filters.universityId));
  const filteredFilieres = filieres.filter(f => !filters.faculteId || f.faculte?.id === parseInt(filters.faculteId));
  const filteredMatieres = matieres.filter(m => !filters.filiereId || m.filiere?.id === parseInt(filters.filiereId));

  // Filtrage robuste selon les 5 critères académiques
  const filteredEpreuves = epreuves.filter(ep => {
    // 1. Institution / Université
    if (filters.universityId && ep.matiere?.filiere?.faculte?.universite?.id !== parseInt(filters.universityId)) return false;
    // 2. Faculté
    if (filters.faculteId && ep.matiere?.filiere?.faculte?.id !== parseInt(filters.faculteId)) return false;
    // 3. Filière
    if (filters.filiereId && ep.matiere?.filiere?.id !== parseInt(filters.filiereId)) return false;
    // 4. Niveau
    if (filters.niveau && ep.matiere?.niveau !== filters.niveau) return false;
    // 5. Session
    if (filters.session && ep.session !== filters.session) return false;
    // 6. Matière
    if (filters.matiereId && ep.matiere?.id !== parseInt(filters.matiereId)) return false;
    // 7. Recherche textuelle libre
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      const matchTitre = ep.titre?.toLowerCase().includes(query);
      const matchMatiere = ep.matiere?.nom?.toLowerCase().includes(query);
      const matchCode = ep.identifiantPublic?.toLowerCase().includes(query);
      if (!matchTitre && !matchMatiere && !matchCode) return false;
    }
    return true;
  });

  return (
    <div className="library-layout" style={{ display: 'flex', minHeight: '100vh', background: '#f0f9ff', color: '#0f172a' }}>
      
      {/* Sidebar de Filtres Glassmorphism Premium */}
      <aside className="filter-sidebar" style={{ 
        width: '340px', 
        background: '#1E293B', 
        padding: '2rem 1.5rem', 
        borderRight: '1px solid rgba(255, 255, 255, 0.08)',
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        overflowY: 'auto',
        height: '100vh',
        position: 'sticky',
        top: 0
      }}>
        
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '0.5rem' }}>
          <button 
            onClick={() => navigate(getDashboardPathForRole(getStoredSession().role), { replace: true })} 
            style={{ 
              background: 'rgba(255, 255, 255, 0.05)', 
              border: '1px solid rgba(255, 255, 255, 0.1)', 
              cursor: 'pointer',
              color: 'white',
              width: '38px',
              height: '38px',
              borderRadius: '12px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              transition: 'all 0.2s'
            }}
            onMouseEnter={(e) => e.currentTarget.style.background = 'rgba(255, 255, 255, 0.1)'}
            onMouseLeave={(e) => e.currentTarget.style.background = 'rgba(255, 255, 255, 0.05)'}
          >
            <ArrowLeft size={18} />
          </button>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <SlidersHorizontal size={20} color="#FFD700" />
            <h2 style={{ fontSize: '1.25rem', fontWeight: '800', margin: 0, letterSpacing: '0.5px' }}>Filtres Académiques</h2>
          </div>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', flex: 1 }}>
          
          {/* SÉLECTEUR UNIVERSITÉ */}
          <div>
            <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.75rem', color: '#475569', letterSpacing: '0.5px' }}>1. UNIVERSITÉ</label>
            <div style={{ position: 'relative' }}>
              <Globe size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: '#38BDF8' }} />
              <select 
                value={filters.universityId}
                onChange={(e) => setFilters({...filters, universityId: e.target.value, faculteId: '', filiereId: '', matiereId: ''})}
                style={{ width: '100%', padding: '12px 12px 12px 35px', borderRadius: '12px', border: '1px solid #e2e8f0', background: 'rgba(0,0,0,0.25)', color: 'white', fontWeight: '600', appearance: 'none', outline: 'none', cursor: 'pointer' }}
              >
                <option value="" style={{ background: '#1E293B', color: 'white' }}>Toutes les Institutions</option>
                {universities.map(u => <option key={u.id} value={u.id} style={{ background: '#1E293B', color: 'white' }}>{u.nom}</option>)}
              </select>
              <ChevronDown size={16} style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none', color: '#475569' }} />
            </div>
          </div>

          {/* SÉLECTEUR FACULTÉ */}
          <div>
            <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.75rem', color: '#475569', letterSpacing: '0.5px' }}>2. FACULTÉ / ÉCOLE</label>
            <div style={{ position: 'relative' }}>
              <BookOpen size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: '#38BDF8' }} />
              <select 
                value={filters.faculteId}
                onChange={(e) => setFilters({...filters, faculteId: e.target.value, filiereId: '', matiereId: ''})}
                style={{ width: '100%', padding: '12px 12px 12px 35px', borderRadius: '12px', border: '1px solid #e2e8f0', background: 'rgba(0,0,0,0.25)', color: 'white', fontWeight: '600', appearance: 'none', outline: 'none', cursor: 'pointer' }}
              >
                <option value="" style={{ background: '#1E293B', color: 'white' }}>Toutes les Facultés</option>
                {filteredFaculties.map(f => <option key={f.id} value={f.id} style={{ background: '#1E293B', color: 'white' }}>{f.nom} ({f.sigle})</option>)}
              </select>
              <ChevronDown size={16} style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none', color: '#475569' }} />
            </div>
          </div>

          {/* SÉLECTEUR FILIÈRE */}
          <div>
            <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.75rem', color: '#475569', letterSpacing: '0.5px' }}>3. FILIÈRE</label>
            <div style={{ position: 'relative' }}>
              <GraduationCap size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: '#38BDF8' }} />
              <select 
                value={filters.filiereId}
                onChange={(e) => setFilters({...filters, filiereId: e.target.value, matiereId: ''})}
                style={{ width: '100%', padding: '12px 12px 12px 35px', borderRadius: '12px', border: '1px solid #e2e8f0', background: 'rgba(0,0,0,0.25)', color: 'white', fontWeight: '600', appearance: 'none', outline: 'none', cursor: 'pointer' }}
              >
                <option value="" style={{ background: '#1E293B', color: 'white' }}>Toutes les Filières</option>
                {filteredFilieres.map(f => <option key={f.id} value={f.id} style={{ background: '#1E293B', color: 'white' }}>{f.nom}</option>)}
              </select>
              <ChevronDown size={16} style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none', color: '#475569' }} />
            </div>
          </div>

          {/* SÉLECTEUR MATIÈRE */}
          <div>
            <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.75rem', color: '#475569', letterSpacing: '0.5px' }}>4. MATIÈRE</label>
            <div style={{ position: 'relative' }}>
              <Layers size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: '#38BDF8' }} />
              <select 
                value={filters.matiereId}
                onChange={(e) => setFilters({...filters, matiereId: e.target.value})}
                style={{ width: '100%', padding: '12px 12px 12px 35px', borderRadius: '12px', border: '1px solid #e2e8f0', background: 'rgba(0,0,0,0.25)', color: 'white', fontWeight: '600', appearance: 'none', outline: 'none', cursor: 'pointer' }}
              >
                <option value="" style={{ background: '#1E293B', color: 'white' }}>Toutes les Matières</option>
                {filteredMatieres.map(m => <option key={m.id} value={m.id} style={{ background: '#1E293B', color: 'white' }}>{m.nom}</option>)}
              </select>
              <ChevronDown size={16} style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none', color: '#475569' }} />
            </div>
          </div>

          {/* SÉLECTEUR SESSION */}
          <div>
            <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.75rem', color: '#475569', letterSpacing: '0.5px' }}>5. SESSION</label>
            <div style={{ position: 'relative' }}>
              <Calendar size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: '#38BDF8' }} />
              <select 
                value={filters.session}
                onChange={(e) => setFilters({...filters, session: e.target.value})}
                style={{ width: '100%', padding: '12px 12px 12px 35px', borderRadius: '12px', border: '1px solid #e2e8f0', background: 'rgba(0,0,0,0.25)', color: 'white', fontWeight: '600', appearance: 'none', outline: 'none', cursor: 'pointer' }}
              >
                <option value="" style={{ background: '#1E293B', color: 'white' }}>Toutes les Sessions</option>
                <option value="HARMATTAN" style={{ background: '#1E293B', color: 'white' }}>Semestre d'Harmattan</option>
                <option value="MOUSSON" style={{ background: '#1E293B', color: 'white' }}>Semestre de Mousson</option>
              </select>
              <ChevronDown size={16} style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none', color: '#475569' }} />
            </div>
          </div>

          {/* BOUTONS DE FILTRAGE PAR NIVEAU D'ÉTUDE */}
          <div>
            <label style={{ display: 'block', fontWeight: '700', marginBottom: '10px', fontSize: '0.75rem', color: '#475569', letterSpacing: '0.5px' }}>NIVEAU D'ÉTUDE</label>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '8px' }}>
              {['', 'L1', 'L2', 'L3', 'M1', 'M2'].map(lvl => (
                <button 
                  key={lvl || 'all'} 
                  onClick={() => setFilters({...filters, niveau: lvl})}
                  style={{ 
                    padding: '10px 5px', 
                    borderRadius: '10px', 
                    border: filters.niveau === lvl ? 'none' : '1px solid #e2e8f0', 
                    background: filters.niveau === lvl ? '#FFD700' : 'rgba(0, 0, 0, 0.2)', 
                    color: filters.niveau === lvl ? 'black' : 'white',
                    fontWeight: '800', 
                    fontSize: '0.8rem',
                    cursor: 'pointer',
                    transition: 'all 0.2s',
                    boxShadow: filters.niveau === lvl ? '0 0 10px rgba(255, 215, 0, 0.3)' : 'none'
                  }}
                >
                  {lvl || 'Tous'}
                </button>
              ))}
            </div>
          </div>

          {/* RÉINITIALISER LES FILTRES */}
          <button 
            onClick={() => setFilters({ universityId: '', faculteId: '', filiereId: '', niveau: '', session: '', matiereId: '', type: 'Tous' })}
            style={{ 
              width: '100%', 
              padding: '12px', 
              borderRadius: '12px', 
              background: 'rgba(255, 255, 255, 0.05)', 
              border: '1px solid rgba(255, 255, 255, 0.1)', 
              color: '#475569', 
              fontWeight: '700', 
              cursor: 'pointer',
              transition: 'all 0.2s',
              marginTop: '10px'
            }}
            onMouseEnter={(e) => { e.currentTarget.style.background = 'rgba(255, 255, 255, 0.1)'; e.currentTarget.style.color = 'white'; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = 'rgba(255, 255, 255, 0.05)'; e.currentTarget.style.color = '#94A3B8'; }}
          >
            Réinitialiser les filtres
          </button>
        </div>

        {/* Bannière IA Premium */}
        <div style={{ 
          background: 'linear-gradient(135deg, #FFD700 0%, #B8860B 100%)', 
          padding: '20px', 
          borderRadius: '24px', 
          color: 'black', 
          marginTop: 'auto',
          boxShadow: '0 8px 20px rgba(255, 215, 0, 0.15)'
        }}>
          <Sparkles size={24} style={{ marginBottom: '10px' }} />
          <h4 style={{ fontSize: '0.95rem', fontWeight: '900', margin: 0 }}>RevisIA_H24 Lab Premium</h4>
          <p style={{ fontSize: '0.75rem', opacity: 0.9, marginTop: '6px', fontWeight: '600', lineHeight: '1.4' }}>Débloquez les corrigés automatiques par IA et résumés vocaux en un clic.</p>
        </div>
      </aside>

      {/* Zone Principale de Rendu */}
      <main style={{ flex: 1, padding: '2.5rem 4rem', overflowY: 'auto', height: '100vh' }}>
        
        <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '3.5rem' }}>
          <div>
            <h1 style={{ fontSize: '2.8rem', fontWeight: '900', color: 'white', margin: 0 }}>Bibliothèque Digitale</h1>
            <p style={{ color: '#475569', fontSize: '1rem', marginTop: '6px', fontWeight: '500' }}>Accès illimité aux ressources académiques de l'Université de Lomé.</p>
          </div>
          <div className="search-bar" style={{ 
            background: 'rgba(0, 0, 0, 0.2)', 
            border: '1px solid #e2e8f0', 
            width: '400px', 
            padding: '12px 20px', 
            borderRadius: '30px',
            display: 'flex',
            alignItems: 'center',
            gap: '12px'
          }}>
            <Search size={20} color="#94A3B8" />
            <input 
              type="text" 
              placeholder="Rechercher par titre, matière..." 
              style={{ color: 'white', background: 'none', border: 'none', outline: 'none', width: '100%', fontSize: '0.95rem', fontWeight: '600' }}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </header>

        {loading ? (
          <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', padding: '10rem 0' }}>
            <div className="loader" style={{ width: '40px', height: '40px', border: '4px solid rgba(255,255,255,0.1)', borderTopColor: '#FFD700', borderRadius: '50%', animation: 'spin 1s linear infinite' }}></div>
          </div>
        ) : filteredEpreuves.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '6rem 0', color: '#475569', background: '#f8fafc', borderRadius: '30px', border: '1px dashed #e2e8f0' }}>
            <BookOpen size={64} style={{ opacity: 0.3, margin: '0 auto 20px', color: '#FFD700' }} />
            <h3 style={{ color: 'white', fontSize: '1.3rem', fontWeight: '800' }}>Aucun document trouvé</h3>
            <p style={{ marginTop: '8px', fontSize: '0.95rem' }}>Ajustez vos filtres académiques ou essayez un autre mot clé.</p>
          </div>
        ) : (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
              <span style={{ color: '#475569', fontSize: '0.95rem', fontWeight: '700' }}>Ressources disponibles ({filteredEpreuves.length})</span>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '25px' }}>
              {filteredEpreuves.map((item) => (
                <motion.div 
                  key={item.id}
                  whileHover={{ translateY: -8, boxShadow: '0 20px 30px rgba(0, 0, 0, 0.3)', borderColor: 'rgba(255,215,0,0.3)' }}
                  style={{ 
                    background: 'var(--elite-card, #1E293B)', 
                    padding: '1.8rem', 
                    borderRadius: '24px', 
                    boxShadow: '0 4px 20px rgba(0,0,0,0.15)', 
                    border: '1px solid rgba(255, 255, 255, 0.05)', 
                    position: 'relative', 
                    transition: 'all 0.3s',
                    display: 'flex',
                    flexDirection: 'column'
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1.2rem' }}>
                    <div style={{ background: '#f8fafc', padding: '10px', borderRadius: '15px', border: '1px solid #e2e8f0' }}>
                      <FileText size={24} color="#FFD700" />
                    </div>
                    <div style={{ textAlign: 'right' }}>
                      <span style={{ display: 'block', fontSize: '0.7rem', fontWeight: '800', color: '#38BDF8', marginBottom: '4px', letterSpacing: '0.5px' }}>
                        {item.matiere?.filiere?.faculte?.sigle || 'UNIVERSITÉ'}
                      </span>
                      <span style={{ 
                        display: 'inline-block',
                        background: item.typeAcces === 'GRATUIT' ? 'rgba(16, 163, 127, 0.15)' : 'rgba(255, 215, 0, 0.15)',
                        color: item.typeAcces === 'GRATUIT' ? '#10A37F' : '#FFD700',
                        padding: '3px 8px',
                        borderRadius: '6px',
                        fontWeight: '800',
                        fontSize: '0.65rem'
                      }}>
                        {item.typeAcces || 'GRATUIT'}
                      </span>
                    </div>
                  </div>
                  
                  <h3 style={{ fontSize: '1.2rem', fontWeight: '800', marginBottom: '8px', lineHeight: '1.4', color: 'white' }}>{item.titre}</h3>
                  <p style={{ fontSize: '0.8rem', color: '#475569', fontWeight: '600', marginBottom: '1.5rem' }}>{item.identifiantPublic}</p>
                  
                  <div style={{ 
                    display: 'grid', 
                    gridTemplateColumns: '1fr 1fr', 
                    gap: '10px', 
                    color: '#475569', 
                    fontSize: '0.8rem', 
                    fontWeight: '700', 
                    marginBottom: '1.5rem', 
                    borderTop: '1px solid #f1f5f9', 
                    paddingTop: '1.2rem',
                    marginTop: 'auto'
                  }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}><Layers size={14} color="#FFD700" /> {item.matiere?.niveau || 'Niveau'}</div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}><Calendar size={14} color="#FFD700" /> {item.session || 'Session'} • {item.annee || 'Année'}</div>
                  </div>

                  <div style={{ display: 'flex', gap: '10px' }}>
                    <a 
                      href={item.fichierUrl?.startsWith('http') ? item.fichierUrl : `${BACKEND_BASE_URL}${item.fichierUrl?.startsWith('/') ? item.fichierUrl : '/' + item.fichierUrl}`}
                      target="_blank" 
                      rel="noreferrer" 
                      className="btn-gold-full" 
                      style={{ 
                        flex: 1, 
                        padding: '12px', 
                        fontSize: '0.85rem', 
                        display: 'flex', 
                        alignItems: 'center', 
                        justifyContent: 'center', 
                        gap: '8px', 
                        textDecoration: 'none',
                        background: '#FFD700',
                        color: 'black',
                        fontWeight: '800',
                        borderRadius: '12px',
                        boxShadow: '0 4px 10px rgba(255, 215, 0, 0.2)',
                        transition: 'all 0.2s'
                      }}
                    >
                      Consulter <ExternalLink size={16} />
                    </a>
                  </div>
                </motion.div>
              ))}
            </div>
          </div>
        )}
      </main>
      
      {/* Styles inline pour le loader spin */}
      <style>{`
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default Library;
