import React from 'react';
import { ArrowLeft } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { getDashboardPathForRole } from '../utils/backHandler';
import { getStoredSession } from '../utils/authSession';

/**
 * Barre de retour visible (web + APK) pour les pages satellites (/library, /marketplace…).
 */
const BackNavBar = ({ label = 'Retour', onBack, fallbackPath, variant = 'light', style = {} }) => {
  const navigate = useNavigate();
  const isDark = variant === 'dark';

  const handleBack = () => {
    if (onBack) {
      onBack();
      return;
    }
    const { role } = getStoredSession();
    const home = fallbackPath || getDashboardPathForRole(role);
    if (window.history.length > 1) {
      navigate(-1);
    } else {
      navigate(home, { replace: true });
    }
  };

  return (
    <button
      type="button"
      onClick={handleBack}
      className="back-nav-bar"
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: '8px',
        marginBottom: '1.25rem',
        padding: '10px 16px',
        borderRadius: '12px',
        border: isDark ? '1px solid rgba(255,255,255,0.1)' : '1px solid #E2E8F0',
        background: isDark ? '#f1f5f9' : 'white',
        color: isDark ? '#94A3B8' : '#334155',
        fontWeight: 600,
        fontSize: '0.9rem',
        cursor: 'pointer',
        boxShadow: isDark ? 'none' : '0 1px 3px rgba(0,0,0,0.06)',
        ...style,
      }}
    >
      <ArrowLeft size={18} />
      {label}
    </button>
  );
};

export default BackNavBar;
